import React, { useState, useEffect } from "react";
import "./App.css";
import {
  FaFacebookF,
  FaInstagram,
  FaYoutube
} from "react-icons/fa";

const API_URL = "http://localhost:8000";

export default function App() {
  const [vista, setVista] = useState("home");

  // --- Empleados ---
  const [empleados, setEmpleados] = useState([]);
  const [nuevoEmpleado, setNuevoEmpleado] = useState({
    nombre: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: ""
  });
  const [empleadoCargado, setEmpleadoCargado] = useState(false);

  // --- Períodos ---
  const [periodos, setPeriodos] = useState([]);
  const [nuevoPeriodo, setNuevoPeriodo] = useState({
    mes: 1, año: 2026, fecha_corte: "", total_general: 0
  });
  const [periodoCargado, setPeriodoCargado] = useState(false);

  // --- Planillas ---
  const [planillas, setPlanillas] = useState([]);
  const [nuevaPlanilla, setNuevaPlanilla] = useState({
    periodo_id: "",
    empleado_id: "",
    sueldo_base: 0,
    horas_extras_diurnas: 0,
    horas_extras_nocturnas: 0,
    horas_nocturnas: 0,
    subsidio_alimentacion: 0,
    bono_extra: 0,
    aplica_nocturnidad: false,
    quincena25_aplica: false
  });
  const [planillaCargado, setPlanillaCargado] = useState(false);
  const [planillaEditandoId, setPlanillaEditandoId] = useState(null);

  // Cargar datos al iniciar
  useEffect(() => {
    const cargarDatos = async () => {
      try {
        const [resEmp, resPer, resPla] = await Promise.all([
          fetch(`${API_URL}/empleado`),
          fetch(`${API_URL}/periodo`),
          fetch(`${API_URL}/planilla`)
        ]);
        if (resEmp.ok) {
          const data = await resEmp.json();
          setEmpleados(data);
        }
        if (resPer.ok) {
          const data = await resPer.json();
          data.sort((a, b) => new Date(a.fecha_corte) - new Date(b.fecha_corte));
          setPeriodos(data);
        }
        if (resPla.ok) {
          const data = await resPla.json();
          setPlanillas(data);
        }
      } catch (error) {
        console.error("Error cargando datos:", error);
      }
    };
    cargarDatos();
  }, []);

  // --- CRUD Empleados ---
  const crearEmpleado = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_URL}/empleado/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoEmpleado),
      });
      if (res.ok) {
        const data = await res.json();
        setEmpleados([...empleados, data]);
        limpiarFormularioEmpleado();
        alert("Empleado creado exitosamente");
      } else {
        const error = await res.json();
        alert(`Error: ${error.detail || "No se pudo crear el empleado"}`);
      }
    } catch (error) {
      console.error("Error al crear empleado:", error);
      alert("Error de conexión con el backend");
    }
  };

  const eliminarEmpleado = async (id) => {
    if (!window.confirm("¿Seguro que deseas eliminar este empleado?")) return;
    try {
      const res = await fetch(`${API_URL}/empleado/${id}`, { method: "DELETE" });
      if (res.ok) {
        setEmpleados(empleados.filter(emp => emp.id !== id));
        alert("Empleado eliminado");
      } else {
        alert("Error al eliminar");
      }
    } catch (error) {
      console.error("Error al eliminar:", error);
    }
  };

  const cargarEmpleado = (emp) => {
    setNuevoEmpleado({
      nombre: emp.nombre,
      area: emp.area,
      puesto: emp.puesto,
      salario_mensual: emp.salario_mensual,
      fecha_ingreso: emp.fecha_ingreso
    });
    setEmpleadoCargado(true);
  };

  const limpiarFormularioEmpleado = () => {
    setNuevoEmpleado({ nombre: "", area: "", puesto: "", salario_mensual: 0, fecha_ingreso: "" });
